import{_ as e,H as t,f as l,i}from"./chunks/framework.CBmkDW73.js";const u=JSON.parse('{"title":"TDD（テスト駆動開発）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/tdd.md","filePath":"ja/skills/tdd.md"}'),r={name:"ja/skills/tdd.md"};function o(d,a,n,s,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="tdd-テスト駆動開発" tabindex="-1">TDD（テスト駆動開発） <a class="header-anchor" href="#tdd-テスト駆動開発" aria-label="Permalink to &quot;TDD（テスト駆動開発）&quot;">​</a></h1><p>計画が承認されたら、各タスクで RED → GREEN → リファクタリング を実行する。各サイクルがgitコミットになる。</p><h2 id="赤" tabindex="-1">赤 <a class="header-anchor" href="#赤" aria-label="Permalink to &quot;赤&quot;">​</a></h2><p>失敗するテストを書く。タスクが完了したとわかる方法を宣言する。</p><h2 id="緑" tabindex="-1">緑 <a class="header-anchor" href="#緑" aria-label="Permalink to &quot;緑&quot;">​</a></h2><p>テストを通過させる最小限のコードを書く。設計は全く気にしない。</p><h2 id="リファクタリング" tabindex="-1">リファクタリング <a class="header-anchor" href="#リファクタリング" aria-label="Permalink to &quot;リファクタリング&quot;">​</a></h2><p>コードを綺麗にする。動作は変更しない。発見または学んだことがあれば仕様ノートを更新する。</p><h2 id="ドキュメント同期" tabindex="-1">ドキュメント同期 <a class="header-anchor" href="#ドキュメント同期" aria-label="Permalink to &quot;ドキュメント同期&quot;">​</a></h2><p>RED-GREEN-リファクタリングの各サイクル後、コミット前にドキュメントを同期：</p><ul><li>仕様が存在する → 実際の状態に合わせて更新する。</li><li>仕様なし（小タスク）→ living docsを直接更新する。</li></ul><h2 id="受け入れ" tabindex="-1">受け入れ <a class="header-anchor" href="#受け入れ" aria-label="Permalink to &quot;受け入れ&quot;">​</a></h2><p>各タスクのacceptance条件はグリーン後に通過しなければならない。自動チェックできない場合は、コミット前に手動で検証する。</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><strong>ここで止まる：</strong></p><ul><li>テストが失敗している。</li><li>Acceptance基準を満たせない。</li><li>コードが仕様と一致しない。</li></ul><p>そうでなければ、<code>ship</code> に進む。</p>',17)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
